export function AgentPermissionsMatrix({
	owner,
	agentId,
	variant = "agent",
}: {
	owner: string;
	/** Required for agent variant; ignored for org-floor. */
	agentId?: string;
	/**
	 * `agent` — per-agent envelope (can only tighten org floor).
	 * `org-floor` — workspace defaults agents inherit (same matrix components).
	 */
	variant?: "agent" | "org-floor";
}) {
	const isOrgFloor = variant === "org-floor";
	const queryClient = useQueryClient();
	const agentQuery = useAgentPermissions(owner, agentId ?? "", {
		enabled: !isOrgFloor && Boolean(agentId),
	});
	const orgQuery = useOrgWritePermissions(owner, { enabled: isOrgFloor });
	const { data, isLoading, isError, error } = isOrgFloor ? orgQuery : agentQuery;

	const queryKey = isOrgFloor
		? orgWritePermissionsQueryKey(owner)
		: agentPermissionsQueryKey(owner, agentId ?? "");

	const saveMutation = useMutation({
		mutationFn: (input: Parameters<typeof updateAgentPermission>[2]) =>
			isOrgFloor
				? updateOrgWritePermission(owner, input)
				: updateAgentPermission(owner, agentId ?? "", input),
		onSuccess: (saved) => {
			queryClient.setQueryData<AgentPermissionsResponse>(queryKey, (prev) =>
				prev ? { ...prev, agent: mergeAgentRow(prev.agent, saved) } : prev,
			);
			void queryClient.invalidateQueries({ queryKey });
			if (isOrgFloor) {
				void queryClient.invalidateQueries({ queryKey: ["agent-permissions"] });
			}
		},
		onError: (err) => {
			toast.error(
				err instanceof Error ? err.message : "Failed to save permission",
			);
		},
	});

	const deleteMutation = useMutation({
		mutationFn: (input: Parameters<typeof deleteAgentPermission>[2]) =>
			isOrgFloor
				? deleteOrgWritePermission(owner, input)
				: deleteAgentPermission(owner, agentId ?? "", input),
		onSuccess: () => {
			void queryClient.invalidateQueries({ queryKey });
			if (isOrgFloor) {
				void queryClient.invalidateQueries({ queryKey: ["agent-permissions"] });
			}
		},
		onError: (err) => {
			toast.error(
				err instanceof Error ? err.message : "Failed to remove override",
			);
		},
	});

	const pending = saveMutation.isPending || deleteMutation.isPending;

	const typeOverrides = useMemo(
