function memberScopeCallbackUrl(
	ownerSlug: string,
	entityScope?: string,
): string {
	if (entityScope) {
		const [entityType, slug, ...rest] = entityScope.split("/");
		if (entityType && slug) {
			const segments: EntityPathSegment[] = [
				{
					entity_type: entityType,
					slug: rest.length > 0 ? [slug, ...rest].join("/") : slug,
				},
			];
			return buildMemoryEntityScopePath(ownerSlug, segments);
		}
	}
	const params = new URLSearchParams({ type: "$member" });
	return `/${ownerSlug}/memory?${params.toString()}`;
}

function MemberGatePrompt({
	title,
	body,
	ctaLabel,
	showCta,
	callbackUrl,
}: {
	title: string;
	body: string;
