  enum?: string[];
  format?: string;
  readOnly?: boolean;
  'x-email'?: boolean;
  'x-image'?: boolean;
  'x-table-column'?: boolean;
}

interface MemberMetadataSchema {
  type?: string;
  properties?: Record<string, MemberSchemaProperty>;
  required?: string[];
}

