const DEFAULT_MEMBER_METADATA_SCHEMA = {
  type: 'object',
  properties: {
    email: {
      type: 'string',
      format: 'email',
      description: 'Email',
      'x-email': true,
      'x-table-column': true,
    },
    image_url: {
