      type: 'string',
      description: 'Status',
      enum: ['active', 'invited'],
      'x-table-column': true,
    },
    display_name: {
      type: 'string',
      description: 'Canonical display name from connectors',
      'x-table-column': true,
    },
    push_name: {
      type: 'string',
      description:
        'Self-chosen name from messaging platforms (WhatsApp push_name, Slack real_name)',
    },
    last_seen_at: {
