		skillRows,
		catalog,
		isLoading,
		isSaving,
		reorderSkills,
		setSkillEnabledAndSave,
		addSkillFromCatalog,
	} = useAgentSkillEditor();

	// Deep-link / refresh onto /skills/:key for a catalog skill that isn't
	// installed yet: seed it into the editor (unsaved) so its row appears and
	// expands — matching the old standalone detail page, which self-seeded.
	useEffect(() => {
		if (!expandedRepo) return;
		if (skillRows.some((row) => row.repo === expandedRepo)) return;
		if (catalog?.catalog.some((entry) => entry.repo === expandedRepo)) {
			addSkillFromCatalog(expandedRepo);
		}
	}, [expandedRepo, skillRows, catalog, addSkillFromCatalog]);

	const cards = useMemo(() => buildSkillIndexCards(skillRows), [skillRows]);
	const sortableIds = useMemo(() => cards.map((card) => card.repo), [cards]);

	const sensors = useSensors(
		useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	const goToCreate = () => {
		void navigate({
			to: "/$owner/agents/$agentId/skills/create",
			params: { owner, agentId },
		});
	};

	const addSkillButton = (
		<Button
			type="button"
			variant="outline"
			size="sm"
			className="h-8 shrink-0 text-xs"
			onClick={goToCreate}
		>
			<Plus className="mr-1.5 h-3.5 w-3.5" />
			Add skill
		</Button>
	);

	const toggleDetail = (repo: string) => {
		// Click the open row again (or its chevron) to collapse back to the list.
		if (repo === expandedRepo) {
			void navigate({
				to: "/$owner/agents/$agentId/skills",
				params: { owner, agentId },
			});
			return;
		}
		void navigate({
			to: "/$owner/agents/$agentId/skills/$skillKey",
			params: { owner, agentId, skillKey: skillRepoToKey(repo) },
		});
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;
		if (!over || active.id === over.id) return;
		reorderSkills(String(active.id), String(over.id));
	};

	if (isLoading) {
		return (
			<div className="space-y-4">
				<p className="text-sm text-muted-foreground">{SKILLS_LEDE}</p>
				<AgentListRowSkeleton rows={2} />
			</div>
		);
	}

	// Empty: single CTA in the empty state (no lede-row Add — same rule as
	// InfraTabScaffold and the connectors list).
	if (cards.length === 0) {
		return (
			<div className="space-y-4">
				<p className="text-sm text-muted-foreground">{SKILLS_LEDE}</p>
				<TabEmptyState
					icon={Sparkles}
					title="No skills yet"
					description="Add a system skill from the catalog or create a custom skill for this agent."
					actionLabel="Add skill"
					onAction={goToCreate}
				/>
			</div>
		);
	}

	return (
		<div className="space-y-4">
			{/* Lede left + outline Add right — matches connector list surfaces. */}
			<div className="flex flex-wrap items-center justify-between gap-3">
				<p className="min-w-0 flex-1 text-sm text-muted-foreground">
					{SKILLS_LEDE}
				</p>
				{addSkillButton}
			</div>

			<DndContext
				sensors={sensors}
				collisionDetection={closestCenter}
				onDragEnd={handleDragEnd}
			>
				<SortableContext
					items={sortableIds}
					strategy={verticalListSortingStrategy}
				>
					<div className="overflow-hidden rounded-lg border">
						{cards.map((card, index) => {
							const expanded = card.repo === expandedRepo;
							return (
								<SortableSkillRow
									key={card.id}
									card={card}
									rank={index + 1}
									disabled={isSaving}
									expanded={expanded}
									isLast={index === cards.length - 1}
									onToggle={() => toggleDetail(card.repo)}
									onToggleEnabled={(next) =>
										void setSkillEnabledAndSave(card.repo, next)
									}
									toggleDisabled={isSaving}
								>
									{expanded ? (
										<AgentSkillDetail
											owner={owner}
											agentId={agentId}
											skillKey={skillRepoToKey(card.repo)}
										/>
									) : null}
								</SortableSkillRow>
							);
						})}
					</div>
				</SortableContext>
			</DndContext>
		</div>
	);
}

function SortableSkillRow({
	card,
	rank,
	disabled,
	expanded,
	isLast,
	onToggle,
	onToggleEnabled,
	toggleDisabled,
	children,
}: {
	card: ReturnType<typeof buildSkillIndexCards>[number];
	rank: number;
	disabled: boolean;
	expanded: boolean;
	isLast: boolean;
	onToggle: () => void;
	onToggleEnabled: (enabled: boolean) => void;
	toggleDisabled: boolean;
	children?: ReactNode;
}) {
	// Collapse-to-drag: an open row can't be reordered, so the expanded form's
	// controls don't fight the drag handle.
	const dragDisabled = disabled || expanded;
	const {
		attributes,
		listeners,
		setNodeRef,
		transform,
		transition,
		isDragging,
	} = useSortable({ id: card.repo, disabled: dragDisabled });

	const style = {
		transform: CSS.Transform.toString(transform),
		transition,
	};

	return (
		<div
			ref={setNodeRef}
			style={style}
			className={cn(
				"bg-background",
				!isLast || expanded ? "border-b" : "",
				isDragging && "z-10 bg-card opacity-80 shadow-sm",
			)}
		>
			<div className="flex items-stretch gap-1 pr-3">
				<button
					type="button"
					className="flex shrink-0 cursor-grab touch-none items-center px-2 text-muted-foreground hover:text-foreground active:cursor-grabbing disabled:cursor-not-allowed disabled:opacity-50"
					aria-label={`Reorder ${card.name}`}
					disabled={dragDisabled}
					{...attributes}
					{...listeners}
				>
					<GripVertical className="h-4 w-4" />
				</button>
				<button
					type="button"
					className={cn(
						"flex min-w-0 flex-1 items-center gap-3 py-2.5 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground",
						!card.enabled && !expanded && "opacity-70",
					)}
					onClick={onToggle}
					aria-expanded={expanded}
				>
					<span className="w-4 shrink-0 text-center text-xs tabular-nums text-muted-foreground">
						{rank}
					</span>
					<div className="min-w-0 flex-1 space-y-1">
						<span className="truncate text-sm font-medium text-foreground">
							{card.name}
						</span>
						{card.description ? (
							<p className="line-clamp-1 text-xs text-muted-foreground">
								{card.description}
							</p>
						) : null}
						<CatalogBadges badges={card.badges} />
					</div>
				</button>
				<div className="flex shrink-0 items-center gap-2 self-center">
					<Switch
						checked={card.enabled}
						onCheckedChange={onToggleEnabled}
						disabled={toggleDisabled}
						aria-label={
							card.enabled ? `Disable ${card.name}` : `Enable ${card.name}`
						}
					/>
					<button
						type="button"
						onClick={onToggle}
						aria-label={expanded ? "Collapse" : "Expand"}
						className="text-muted-foreground transition-colors hover:text-foreground"
					>
						<ChevronRight
							className={cn(
								"h-4 w-4 transition-transform",
								expanded && "rotate-90",
							)}
						/>
					</button>
				</div>
			</div>
			{expanded && children ? (
				<div className="border-t border-border px-4 py-4">{children}</div>
			) : null}
		</div>
	);
}

/**
 * Shared back affordance for agent sub-pages: an icon-only button in a left
 * gutter, top-aligned with the page title so it shares the title's row instead
 * of taking its own, and with no text label (which just repeated the section
 * name — the name rides `aria-label` for screen readers). Use this anywhere a
 * detail/create page needs a "back to <section>" control so every tab matches.
 */
export function WithBackGutter({
	onBack,
	backLabel,
	children,
}: {
	onBack: () => void;
	backLabel: string;
	children: ReactNode;
}) {
	// The arrow lives in the left margin (absolute, `right-full`) so it doesn't
	// indent the content — the page body stays full-width and centered under the
	// tab bar, with the arrow hanging in the gutter, top-aligned with the title.
	return (
		<div className="relative">
			<Button
				type="button"
				variant="ghost"
				size="icon"
				className="absolute right-full top-0 mr-1 size-8 text-muted-foreground hover:text-foreground"
				aria-label={`Back to ${backLabel}`}
				onClick={onBack}
			>
				<ArrowLeft className="h-4 w-4" />
			</Button>
			{children}
		</div>
	);
}

/**
 * Centered, sticky sub-page header for agent detail views: the item title sits
 * centered under the agent tab bar (matching the centered agent header), with a
 * back arrow pinned in the left gutter so it doesn't pull the title off-center.
