	action?: ReactNode;
}) {
	return (
		<div className="sticky top-0 z-10 mb-2 bg-background py-2">
			<div className="relative flex items-center justify-center gap-1">
				<Button
					type="button"
					variant="ghost"
					size="icon"
					className="absolute left-0 size-8 shrink-0 text-muted-foreground hover:text-foreground"
					aria-label={`Back to ${backLabel}`}
