import { Link, useNavigate } from "@tanstack/react-router";
import { Pencil, Plus, Radio, Trash2 } from "lucide-react";
import { useMemo, useState } from "react";
import { AgentTabShell } from "@/components/agents/agent-subpage-shell";
import {
	KindBadge,
	OutputChips,
} from "@/components/agents/behaviors/behavior-badges";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { StatusBadge } from "@/components/ui/status-badge";
import { useAgentWatchersList, useDeleteWatcher } from "@/hooks/use-watchers";
import {
	type Behavior,
	type BehaviorFacets,
	DEFAULT_FACETS,
	filterBehaviors,
	type KindFacet,
	mergeBehaviors,
	type OutputFacet,
	type StateFacet,
} from "@/lib/behaviors/model";
import { cn, FILLED_BOX } from "@/lib/utils";

const KIND_FACETS: { value: KindFacet; label: string }[] = [
	{ value: "all", label: "All" },
	{ value: "event", label: "Event" },
	{ value: "schedule", label: "Schedule" },
	{ value: "manual", label: "Manual" },
];
const OUTPUT_FACETS: { value: OutputFacet; label: string }[] = [
	{ value: "any", label: "Any output" },
	{ value: "reply", label: "Reply" },
	{ value: "silent", label: "Save in Lobu" },
];
const STATE_FACETS: { value: StateFacet; label: string }[] = [
	{ value: "any", label: "Any state" },
	{ value: "active", label: "Active" },
	{ value: "failing", label: "Failing" },
];

function FacetGroup<T extends string>({
	options,
	value,
	onChange,
}: {
	options: { value: T; label: string }[];
	value: T;
	onChange: (value: T) => void;
}) {
	return (
		<div className="inline-flex rounded-md border bg-muted/30 p-0.5 text-sm">
			{options.map((option) => (
				<button
					key={option.value}
					type="button"
					aria-pressed={value === option.value}
					onClick={() => onChange(option.value)}
					className={cn(
						"rounded px-3 py-1 transition-colors",
						value === option.value
							? "bg-background text-foreground shadow-sm"
							: "text-muted-foreground hover:text-foreground",
					)}
				>
					{option.label}
				</button>
			))}
		</div>
	);
}

function RemoveControl({
	pending,
	onConfirm,
}: {
	pending: boolean;
	onConfirm: () => void;
}) {
	const [confirming, setConfirming] = useState(false);
	if (!confirming) {
		return (
			<Button
				type="button"
				variant="ghost"
				size="icon"
				className="text-muted-foreground hover:text-destructive"
				aria-label="Delete"
				onClick={() => setConfirming(true)}
			>
				<Trash2 className="h-4 w-4" />
			</Button>
		);
	}
	return (
		<div className="flex items-center gap-1">
			<Button
				type="button"
				variant="destructive"
				size="sm"
				disabled={pending}
				onClick={onConfirm}
			>
				Delete
			</Button>
			<Button
				type="button"
				variant="ghost"
				size="sm"
				onClick={() => setConfirming(false)}
			>
				Cancel
			</Button>
		</div>
	);
}

function BehaviorRow({
	behavior,
	agentName,
	owner,
	agentId,
	onRemove,
	removing,
}: {
	behavior: Behavior;
	agentName: string;
	owner: string;
	agentId: string;
	onRemove: () => void;
	removing: boolean;
}) {
	const watcherId = behavior.watcher.behavior_id;
	const editClass =
		"inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground";
	return (
		<div className={cn(FILLED_BOX, "flex items-center gap-1 pr-2")}>
			<Link
				to="/$owner/agents/$agentId/behaviors/$watcherId"
				params={{ owner, agentId, watcherId }}
				search={{ view: "activity", run_id: undefined }}
				className="block min-w-0 flex-1 rounded-md px-4 py-3 transition-colors hover:bg-accent/50"
			>
				<div className="flex w-full flex-wrap items-center gap-x-3 gap-y-2">
					<KindBadge kind={behavior.kind} />
					<p className="min-w-[240px] flex-1 text-sm leading-snug">
						<span className="text-muted-foreground">{behavior.when}, </span>
						<span className="font-medium">{agentName} </span>
						<span>{behavior.does}.</span>
					</p>
					<OutputChips output={behavior.output} />
					{behavior.state === "error" ? (
						<StatusBadge status="error" showDot>
							Failing
						</StatusBadge>
					) : null}
				</div>
			</Link>
			<Link
				to="/$owner/agents/$agentId/behaviors/$watcherId"
				params={{ owner, agentId, watcherId }}
				search={{ view: "definition", run_id: undefined }}
				className={editClass}
				aria-label="Edit"
			>
				<Pencil className="h-4 w-4" />
			</Link>
			<RemoveControl pending={removing} onConfirm={onRemove} />
		</div>
	);
}

export function BehaviorsIndex({
	owner,
	agentId,
	agentName,
}: {
	owner: string;
	agentId: string;
	agentName: string;
}) {
	const navigate = useNavigate();
	const [facets, setFacets] = useState<BehaviorFacets>(DEFAULT_FACETS);
	const watchers = useAgentWatchersList(agentId);
	const deleteBehavior = useDeleteWatcher();
	const behaviors = useMemo(
		() => mergeBehaviors(watchers.data ?? []),
		[watchers.data],
	);
	const visible = useMemo(
		() => filterBehaviors(behaviors, facets),
		[behaviors, facets],
	);

	if (!watchers.isLoading && behaviors.length === 0) {
		return (
			<AgentTabShell>
				<TabEmptyState
					icon={Radio}
					title="No behaviors yet"
					description="Behaviors define when and where the agent acts autonomously. Add one triggered by an event, schedule, or explicit call."
					actionLabel="New behavior"
					onAction={() =>
						void navigate({
							to: "/$owner/agents/$agentId/behaviors/new",
							params: { owner, agentId },
							search: {},
						})
					}
				/>
			</AgentTabShell>
		);
	}

	return (
		<AgentTabShell>
			<div className="mb-4 flex items-start justify-between gap-4">
				<div>
					<h2 className="text-xl font-semibold">Behaviors</h2>
					<p className="mt-1 max-w-xl text-sm text-muted-foreground">
						Behaviors define when and where the agent acts autonomously — across
						connector events, schedules, and explicit calls.
					</p>
				</div>
				<Button asChild className="shrink-0">
					<Link
						to="/$owner/agents/$agentId/behaviors/new"
						params={{ owner, agentId }}
						search={{}}
					>
						<Plus className="mr-1.5 h-4 w-4" />
						New behavior
					</Link>
				</Button>
			</div>

			<div className="mb-4 flex flex-wrap items-center gap-2">
				<FacetGroup
					options={KIND_FACETS}
					value={facets.kind}
					onChange={(kind) => setFacets((current) => ({ ...current, kind }))}
				/>
				<FacetGroup
					options={OUTPUT_FACETS}
					value={facets.output}
					onChange={(output) =>
						setFacets((current) => ({ ...current, output }))
					}
				/>
				<FacetGroup
					options={STATE_FACETS}
					value={facets.state}
					onChange={(state) => setFacets((current) => ({ ...current, state }))}
				/>
			</div>

			{watchers.isLoading ? (
				<div className="flex flex-col gap-2">
					{[0, 1, 2].map((index) => (
						<Skeleton key={index} className="h-16 w-full rounded-lg" />
					))}
				</div>
			) : visible.length === 0 ? (
				<TabEmptyState
					icon={Radio}
					title="No behaviors match these filters"
					description="Adjust the trigger, output, or state filters to see more."
				/>
			) : (
				<div className="flex flex-col gap-2">
					{visible.map((behavior) => (
						<BehaviorRow
							key={behavior.key}
							behavior={behavior}
							agentName={agentName}
							owner={owner}
							agentId={agentId}
							removing={deleteBehavior.isPending}
							onRemove={() =>
								deleteBehavior.mutate(behavior.watcher.behavior_id)
							}
						/>
					))}
				</div>
			)}
		</AgentTabShell>
	);
}

