import { Check, ChevronsUpDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { CommandItem } from "@/components/ui/command";
import {
	type InferenceCatalogItem,
	type InferenceProviderItem,
	useInferenceProviderCatalog,
	useInferenceProviders,
} from "@/lib/api/inference-providers";
import { cn } from "@/lib/utils";

/**
 * A model ref offered by the picker. `value` is what gets stored (a
 * `provider/model` ref or `auto`); the rest is display metadata.
 */
export interface ModelOption {
	value: string;
	provider: string;
	model: string;
	isDefault: boolean;
}

/**
 * Build routable autocomplete entries from both org-owned providers and
 * deployment-level providers. The latter have no `inference_providers` row, so
 * omitting catalog entries marked `systemAvailable` made their current models
 * disappear from the picker even though the worker could route them.
 */
export function buildModelOptions(
	providers: readonly InferenceProviderItem[],
	catalog: readonly InferenceCatalogItem[],
): ModelOption[] {
	const catalogBySlug = new Map(catalog.map((entry) => [entry.slug, entry]));
	const byValue = new Map<string, ModelOption>();

	const add = (args: {
		slug: string;
		provider: string;
		model: string | null | undefined;
		isDefault: boolean;
	}) => {
		const model = args.model?.trim();
		if (!model) return;
		const value = `${args.slug}/${model}`;
		if (byValue.has(value)) return;
		byValue.set(value, {
			value,
			provider: args.provider,
			model,
			isDefault: args.isDefault,
		});
	};

	for (const provider of providers) {
		const catalogEntry =
			catalogBySlug.get(provider.kind) ?? catalogBySlug.get(provider.slug);
		const common = {
			slug: provider.slug,
			provider: provider.displayName || provider.slug,
			isDefault: provider.isDefault,
		};
		// The org-pinned model leads, then the catalog's recommended default and
		// remaining curated models complete the searchable suggestions.
		add({ ...common, model: provider.capabilities.text?.model });
		add({ ...common, model: catalogEntry?.defaultModel });
		for (const model of catalogEntry?.models ?? []) {
			add({ ...common, model });
		}
	}

