}

export function shouldOfferFreeformModel(
	query: string,
	options: readonly ModelOption[],
): boolean {
	const trimmed = query.trim();
	return (
		trimmed.length > 0 &&
		trimmed !== "auto" &&
		!options.some((option) => option.value === trimmed)
	);
}

/**
 * Search-select for a model ref, sourced from the org's inference-providers.
 * Each provider that maps a text model contributes a `slug/model` option; the
 * literal `auto` (newest model for a provider) is always offered, and a
 * free-text escape hatch ("Use <query>") lets callers pin any ref the org
 * hasn't mapped yet — so the picker never blocks a valid value it doesn't know.
 *
 * `value === ""` means "no override" — the field inherits the next layer down
 * (agent default, then org default). `placeholder` names that inherited source
 * so an empty picker reads as intentional ("Use org default" vs "Use agent
 * default"), not blank.
 *
 * Uses the `<Combobox>` primitive per DESIGN_GUIDELINES §5 (no hand-rolled
 * Popover + Command shell).
 */
export function ModelSelector({
	value,
	onChange,
	placeholder,
	disabled,
	className,
}: {
	value: string;
	onChange: (value: string) => void;
	/** Shown when nothing is selected — names the inherited fallback. */
	placeholder: string;
	disabled?: boolean;
	className?: string;
}) {
	const { data: providers = [] } = useInferenceProviders();
	// Catalog carries the curated autocomplete shortlist. It also identifies
	// deployment-level providers, which are routable without an org-owned row.
	const { data: catalog = [] } = useInferenceProviderCatalog();
	const options = buildModelOptions(providers, catalog);

	const known = options.find((o) => o.value === value);
	// A stored value the org no longer maps (provider removed, hand-typed ref):
	// still show it so editing doesn't silently drop the user's choice.
	const label = value === "auto" ? "auto" : (known?.value ?? value);

