import { useNavigate } from '@tanstack/react-router';
import { ChevronRight, Plus, ShieldCheck } from 'lucide-react';
import { type ReactNode, useMemo } from 'react';
import { toast } from 'sonner';
import { AgentGuardrailDetail } from '@/components/agents/agent-guardrail-detail';
import { AgentTabIntro } from '@/components/agents/agent-tab-intro';
import { CatalogBadges } from '@/components/agents/catalog-badges';
import {
  buildGuardrailRows,
  toggleGuardrailEnabled,
} from '@/components/agents/guardrails-editor';
import { AgentListRowSkeleton } from '@/components/agents/agent-loading-shells';
import { TabEmptyState } from '@/components/entity-tabs/tab-states';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import {
  useAgentConfig,
  useGuardrailsCatalog,
  useGuardrailTrips,
  useUpdateAgentConfig,
} from '@/lib/api';
import { setCustomGuardrailEnabled } from '@/lib/custom-guardrail-edits';
import {
  buildGuardrailIndexCards,
  type GuardrailIndexCard,
} from '@/lib/guardrail-index-cards';
import { cn } from '@/lib/utils';

export function AgentGuardrailsIndex({
  owner,
  agentId,
  expandedName,
}: {
  owner: string;
  agentId: string;
  /** When set, that guardrail's row is expanded in place to show its config. */
  expandedName?: string;
}) {
  const navigate = useNavigate();
  const { data: agentConfig, isLoading: isConfigLoading } =
    useAgentConfig(agentId);
  // `data` is `null` when the gateway hasn't deployed the catalog endpoint yet.
  const { data: catalog, isLoading: isCatalogLoading } =
    useGuardrailsCatalog(agentId);
  const { data: trips = [] } = useGuardrailTrips(agentId);
  const updateAgentConfig = useUpdateAgentConfig(agentId);

  const handleToggleEnabled = async (
    card: GuardrailIndexCard,
    enabled: boolean
  ) => {
    if (!agentConfig) {
      toast.error('Still loading agent settings — try again in a moment');
      return;
    }
    try {
      if (card.kind === 'custom') {
        await updateAgentConfig.mutateAsync({
          guardrailsInline: setCustomGuardrailEnabled(
            agentConfig.guardrailsInline ?? [],
            card.name,
            enabled
          ),
        });
      } else {
        const rows = buildGuardrailRows(agentConfig, catalog ?? []);
        await updateAgentConfig.mutateAsync({
          guardrails: toggleGuardrailEnabled(rows, card.name, enabled),
        });
      }
      toast.success(enabled ? 'Guardrail enabled' : 'Guardrail disabled');
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : 'Failed to save guardrail'
      );
    }
  };

  const catalogUnavailable = catalog === null;

  const cards = useMemo(() => {
    const builtinRows = buildGuardrailRows(agentConfig, catalog ?? []);
    const custom = agentConfig?.guardrailsInline ?? [];
    const tripCounts = new Map<string, number>();
    for (const trip of trips) {
      tripCounts.set(
        trip.guardrailName,
        (tripCounts.get(trip.guardrailName) ?? 0) + 1
      );
    }
    return buildGuardrailIndexCards(builtinRows, custom, tripCounts);
  }, [agentConfig, catalog, trips]);

  const toggleDetail = (name: string) => {
    // Click the open row again (or its chevron) to collapse back to the list.
    if (name === expandedName) {
      void navigate({
        to: '/$owner/agents/$agentId/guardrails',
        params: { owner, agentId },
      });
      return;
    }
    void navigate({
      to: '/$owner/agents/$agentId/guardrails/$name',
      params: { owner, agentId, name: encodeURIComponent(name) },
    });
  };

  const goToCreate = () => {
    void navigate({
      to: '/$owner/agents/$agentId/guardrails/create',
      params: { owner, agentId },
    });
  };

  const isLoading = isConfigLoading || isCatalogLoading;

  // Empty (and done loading): the empty state IS the whole tab — no intro/header
  // button alongside the empty state's own "New guardrail" (that just doubled
  // the affordance).
  if (!isLoading && cards.length === 0) {
    return (
      <div className="space-y-6">
        {catalogUnavailable ? (
          <TabEmptyState
            icon={ShieldCheck}
            title="Guardrails catalog unavailable"
            description="Guardrails will appear here once the gateway publishes its catalog."
            actionLabel="New guardrail"
            onAction={goToCreate}
          />
        ) : (
          <TabEmptyState
            icon={ShieldCheck}
            title="No guardrails yet"
            description="Enable a built-in in lobu.toml or write a custom policy guardrail."
            actionLabel="New guardrail"
            onAction={goToCreate}
          />
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <AgentTabIntro
        description="Each guardrail short-circuits this agent's input, output, or tool-call stages. Built-ins are toggle-only; add a custom guardrail to judge messages against a policy you write."
        action={
          !isLoading ? (
            <Button type="button" onClick={goToCreate}>
              <Plus className="mr-1.5 h-4 w-4" />
              New guardrail
            </Button>
          ) : undefined
        }
      />

      {isLoading ? (
        <AgentListRowSkeleton rows={3} />
      ) : (
        <div className="flex flex-col gap-2">
          {cards.map((card) => {
            const expanded = card.name === expandedName;
            return (
              <GuardrailCard
                key={card.id}
                card={card}
                expanded={expanded}
                onToggle={() => toggleDetail(card.name)}
                onToggleEnabled={(next) => void handleToggleEnabled(card, next)}
                toggleDisabled={card.unknown || updateAgentConfig.isPending}
              >
                {expanded ? (
                  <AgentGuardrailDetail
                    owner={owner}
                    agentId={agentId}
                    name={card.name}
                  />
                ) : null}
              </GuardrailCard>
            );
          })}
        </div>
      )}
    </div>
  );
}

function GuardrailCard({
  card,
  expanded,
  onToggle,
  onToggleEnabled,
  toggleDisabled,
  children,
}: {
  card: GuardrailIndexCard;
  expanded: boolean;
  onToggle: () => void;
  onToggleEnabled: (enabled: boolean) => void;
  toggleDisabled: boolean;
  children?: ReactNode;
}) {
  return (
    <div className="rounded-lg bg-card">
      <div className="flex items-center gap-2 pr-4">
        <button
          type="button"
          onClick={onToggle}
          aria-expanded={expanded}
          className={cn(
            'flex min-w-0 flex-1 items-center gap-3 p-3 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground',
            !card.enabled && !card.unknown && !expanded && 'opacity-70'
          )}
        >
          <ShieldCheck className="h-4 w-4 shrink-0" />
          <div className="min-w-0 flex-1 space-y-2">
            <span
              className={cn(
                'truncate text-sm',
                card.unknown ? 'font-mono text-xs' : 'font-medium'
              )}
            >
              {card.name}
            </span>
            {card.kind === 'custom' && card.description ? (
              <p className="line-clamp-1 text-xs text-muted-foreground">
                {card.description}
              </p>
            ) : (
              <p className="text-xs text-muted-foreground">
                {card.tripCount > 0
                  ? `${card.tripCount} recent ${card.tripCount === 1 ? 'catch' : 'catches'}`
                  : 'No recent catches'}
              </p>
            )}
            <CatalogBadges badges={card.badges} />
          </div>
        </button>
        <Switch
          checked={card.enabled}
          onCheckedChange={onToggleEnabled}
          disabled={toggleDisabled}
          aria-label={
            card.enabled ? `Disable ${card.name}` : `Enable ${card.name}`
          }
        />
        <button
          type="button"
          onClick={onToggle}
          aria-label={expanded ? 'Collapse' : 'Expand'}
          className="shrink-0 text-muted-foreground transition-colors hover:text-foreground"
        >
          <ChevronRight
            className={cn(
              'h-4 w-4 transition-transform',
              expanded && 'rotate-90'
            )}
          />
        </button>
      </div>
      {expanded && children ? (
        <div className="border-t border-border px-4 py-4">{children}</div>
      ) : null}
    </div>
  );
}

